<!doctype html><html lang="it"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:10px;color:#1f2937}h1{font-size:22px;margin:0}.head{display:flex;justify-content:space-between;border-bottom:2px solid #243b53;padding-bottom:18px;margin-bottom:20px}.muted{color:#64748b}table{width:100%;border-collapse:collapse;margin-top:20px}th{background:#eef2f7;text-align:left}th,td{padding:8px;border-bottom:1px solid #dbe2ea}.right{text-align:right}.totals{margin-left:55%;width:45%}.totals td:first-child{font-weight:bold}.footer{position:fixed;bottom:0;font-size:8px;color:#64748b}</style></head><body>
<div class="head"><div><h1><?= htmlspecialchars($definition['singular']) ?> <?= htmlspecialchars($document['number']) ?></h1><p class="muted">Data <?= date('d/m/Y', strtotime($document['document_date'])) ?></p></div><div><strong><?= htmlspecialchars($organization['business_name'] ?? '') ?></strong><br><?= htmlspecialchars($organization['address'] ?? '') ?><br><?= htmlspecialchars(($organization['postal_code'] ?? '') . ' ' . ($organization['city'] ?? '')) ?><br>P.IVA <?= htmlspecialchars($organization['vat_number'] ?? '') ?></div></div>
<h3>Destinatario</h3><p><strong><?= htmlspecialchars($document['counterparty_name']) ?></strong></p><p><?= nl2br(htmlspecialchars($document['subject'] ?? '')) ?></p>
<table><thead><tr><th>#</th><th>Descrizione</th><th class="right">Quantità</th><th class="right">Prezzo</th><th class="right">IVA</th><th class="right">Totale</th></tr></thead><tbody><?php foreach ($lines as $line): ?><tr><td><?= (int) $line['line_number'] ?></td><td><?= htmlspecialchars($line['description']) ?></td><td class="right"><?= number_format((float) $line['quantity'], 2, ',', '.') ?></td><td class="right"><?= number_format((float) $line['unit_price'], 2, ',', '.') ?> €</td><td class="right"><?= number_format((float) $line['vat_rate'], 2, ',', '.') ?>%</td><td class="right"><?= number_format((float) $line['total_amount'], 2, ',', '.') ?> €</td></tr><?php endforeach; ?></tbody></table>
<table class="totals"><tr><td>Imponibile</td><td class="right"><?= number_format((float) $document['taxable_total'], 2, ',', '.') ?> €</td></tr><tr><td>IVA</td><td class="right"><?= number_format((float) $document['vat_total'], 2, ',', '.') ?> €</td></tr><tr><td>Totale</td><td class="right"><strong><?= number_format((float) $document['total'], 2, ',', '.') ?> €</strong></td></tr></table>
<?php if ($document['notes']): ?><h3>Note</h3><p><?= nl2br(htmlspecialchars($document['notes'])) ?></p><?php endif; ?><div class="footer">Documento generato da Luna2 · <?= date('d/m/Y H:i') ?></div>
</body></html>
